    [89,24,"הכיור היה בין האולם ולמזבח, ומשוך כלפי הדרום. בין האולם ולמזבח, עשרים ושתים אמה. ושתים עשרה מעלות היו שם, רום מעלה חצי אמה, ושלחה אמה. אמה אמה ורבד שלש, ואמה אמה ורבד שלש. והעליונה, אמה אמה ורבד ארבע. רבי יהודה אומר, העליונה, אמה אמה ורבד חמש:"],
    [89,25,"פתחו של אולם, גבהו ארבעים אמה, ורחבו עשרים אמה. וחמש מלתראות של מילת היו על גביו. התחתונה עודפת על הפתח אמה מזה ואמה מזה. שלמעלה ממנה עודפת עליה אמה מזה ואמה מזה. נמצאת העליונה שלשים אמה. ונדבך של אבנים היה בין כל אחת ואחת:"],
    [89,26,"וכלונסות של ארז היו קבועין מכתלו של היכל לכתלו של אולם, כדי שלא יבעט. ושרשרות של זהב היו קבועות בתקרת האולם, שבהן פרחי כהנה עולין ורואין את העטרת, שנאמר (זכריה ו), והעטרת תהיה לחלם ולטוביה ולידעיה ולחן בן צפניה לזכרון בהיכל ה׳. גפן של זהב היתה עומדת על פתחו של היכל, ומדלה על גבי כלונסות. כל מי שהוא מתנדב עלה, או גרגיר, או אשכול, מביא ותולה בה. אמר רבי אליעזר ברבי צדוק, מעשה היה, ונמנו עליה שלש מאות כהנים:"],
    [89,28,"פתחו של היכל, גבהו עשרים אמה ורחבו עשר אמות. וארבע דלתות היו לו, שתים בפנים ושתים בחוץ, שנאמר (יחזקאל מא), ושתים דלתות להיכל ולקדש. החיצונות נפתחות לתוך הפתח לכסות עביו של כתל, והפנימיות נפתחות לתוך הבית לכסות אחר הדלתות, שכל הבית טוח בזהב, חוץ מאחר הדלתות. רבי יהודה אומר, בתוך הפתח היו עומדות, וכמין אצטרמיטה היו, ונקפלות לאחוריהן, אלו שתי אמות ומחצה, ואלו שתי אמות ומחצה, חצי אמה מזוזה מכאן, וחצי אמה מזוזה מכאן, שנאמר (שם), ושתים דלתות לדלתות שתים מוסבות דלתות, שתים לדלת אחת ושתי דלתות לאחרת:"],
    [89,29,"ושני פשפשין היו לו לשער הגדול, אחד בצפון, ואחד בדרום. שבדרום, לא נכנס בו אדם מעולם, ועליו הוא מפרש על ידי יחזקאל, שנאמר (שם מד), ויאמר אלי ה׳ השער הזה סגור יהיה לא יפתח ואיש לא יבא בו כי ה׳ אלהי ישראל בא בו והיה סגור. נטל את המפתח ופתח את הפשפש, ונכנס להתא, ומהתא להיכל. רבי יהודה אומר, בתוך עביו של כתל היה מהלך, עד שנמצא עומד בין שני השערים, ופתח את החיצונות מבפנים ואת הפנימיות מבחוץ:"],
    [89,30,"ושלשים ושמנה תאים היו שם, חמשה עשר בצפון, חמשה עשר בדרום, ושמנה במערב. שבצפון ושבדרום, חמשה על גבי חמשה, וחמשה על גביהם. ושבמערב, שלשה על גבי שלשה, ושנים על גביהם. ושלשה פתחים היו לכל אחד ואחד, אחד לתא מן הימין, ואחד לתא מן השמאל, ואחד לתא שעל גביו. ובקרן מזרחית צפונית היו חמשה פתחים, אחד לתא מן הימין, ואחד לתא שעל גביו, ואחד למסבה, ואחד לפשפש, ואחד להיכל:"],
    [89,31,"התחתונה, חמש, ורבד שש. והאמצעית, שש, ורבד שבע. והעליונה, שבע, שנאמר (מלכים א ו), היציע התחתונה חמש באמה רחבה והתיכנה שש באמה רחבה והשלישית שבע באמה רחבה:"],
    [89,32,"ומסבה היתה עולה מקרן מזרחית צפונית לקרן צפונית מערבית, שבה היו עולים לגגות התאים. היה עולה במסבה ופניו למערב. הלך על כל פני הצפון, עד שהוא מגיע למערב. הגיע למערב, והפך פניו לדרום. הלך כל פני מערב עד שהוא מגיע לדרום. הגיע לדרום, והפך פניו למזרח. היה מהלך בדרום, עד שהוא מגיע לפתחה של עליה, שפתחה של עליה פתוח לדרום. ובפתחה של עליה היו שני כלונסות של ארז, שבהן היו עולין לגגה של עליה. וראשי פספסין מבדילים בעליה בין הקדש לבין קדש הקדשים. ולולין היו פתוחין בעליה לבית קדש הקדשים, שבהן היו משלשלין את האמנים בתבות, כדי שלא יזונו עיניהן מבית קדשי הקדשים:"],
    [89,33,"וההיכל מאה על מאה, על רום מאה. האטם שש אמות, וגבהו ארבעים אמה, אמה כיור, ואמתים בית דלפה, ואמה תקרה, ואמה מעזיבה, וגבה של עליה ארבעים אמה, ואמה כיור, ואמתים בית דלפה, ואמה תקרה, ואמה מעזיבה, ושלש אמות מעקה, ואמה כלה עורב, רבי יהודה אומר, לא היה כלה עורב עולה מן המדה, אלא ארבע אמות היה מעקה:"],
    [89,34,"מהמזרח למערב מאה אמה, כתל האולם חמש, והאולם אחד עשר, כתל ההיכל שש, ותוכו ארבעים אמה, אמה טרקסין, ועשרים אמה בית קדש הקדשים, כתל ההיכל שש, והתא שש, וכתל התא חמש. מן הצפון לדרום שבעים אמה, כתל המסבה חמש, והמסבה שלש, כתל התא חמש, והתא שש, כתל ההיכל שש, ותוכו עשרים אמה, כתל ההיכל שש, והתא שש, וכתל התא חמש, ובית הורדת המים שלש אמות, והכתל חמש אמות. האולם עודף עליו חמש עשרה אמה מן הצפון, וחמש עשרה אמה מן הדרום, והוא היה נקרא בית החליפות, ששם גונזים את הסכינים. וההיכל צר מאחריו, ורחב מלפניו, ודומה לארי, שנאמר (ישעיה כט), הוי אריאל אריאל קרית חנה דוד, מה הארי צר מאחריו ורחב מלפניו, אף ההיכל צר מאחריו ורחב מלפניו:"],
    [89,36,"כל העזרה היתה ארך מאה ושמונים ושבע על רחב מאה ושלשים וחמש. מן המזרח למערב מאה ושמונים ושבע, מקום דריסת ישראל אחת עשרה אמה, מקום דריסת הכהנים אחת עשרה אמה, המזבח שלשים ושתים, בין האולם ולמזבח עשרים ושתים אמה, ההיכל מאה אמה, ואחת עשרה אמה לאחורי בית הכפרת:"],
    [89,37,"מן הצפון לדרום מאה ושלשים וחמש, הכבש והמזבח ששים ושתים. מן המזבח לטבעות שמנה אמות, מקום הטבעות עשרים וארבע, מן הטבעות לשלחנות ארבע, מן השלחנות ולננסין ארבע. מן הננסין לכתל העזרה שמנה אמות, והמותר בין הכבש לכתל ומקום הננסין:"],
    [89,38,"שש לשכות היו בעזרה, שלש בצפון ושלש בדרום. שבצפון, לשכת המלח, לשכת הפרוה, לשכת המדיחים. לשכת המלח, שם היו נותנים מלח לקרבן. לשכת הפרוה, שם היו מולחין עורות קדשים, ועל גגה היה בית הטבילה לכהן גדול ביום הכפורים. לשכת המדיחין, ששם היו מדיחין קרבי הקדשים. ומשם מסבה עולה לגג בית הפרוה:"],
    [89,39,"שבדרום, לשכת העץ, לשכת הגולה, לשכת הגזית. לשכת העץ, אמר רבי אליעזר בן יעקב, שכחתי מה היתה משמשת. אבא שאול אומר, לשכת כהן גדול, והיא היתה אחורי שתיהן, וגג שלשתן שוה. לשכת הגולה, שם היה בור קבוע, והגלגל נתון עליו, ומשם מספיקים מים לכל העזרה. לשכת הגזית, שם היתה סנהדרי גדולה של ישראל יושבת ודנה את הכהנה, וכהן שנמצא בו פסול, לובש שחורים ומתעטף שחורים, ויוצא והולך לו. ושלא נמצא בו פסול, לובש לבנים ומתעטף לבנים, נכנס ומשמש עם אחיו הכהנים. ויום טוב היו עושים, שלא נמצא פסול בזרעו של אהרן הכהן, וכך היו אומרים, ברוך המקום ברוך הוא, שלא נמצא פסול בזרעו של אהרן. וברוך הוא, שבחר באהרן ובבניו לעמד לשרת לפני ה׳ בבית קדשי הקדשים:"],
    [337,3,"מצות עשה לעשות בית לה׳ מוכן להיות מקריבים בו הקרבנות. וחוגגין אליו שלש פעמים בשנה שנאמר \"ועשו לי מקדש\". וכבר נתפרש בתורה משכן שעשה משה רבנו. והיה לפי שעה שנאמר \"כי לא באתם עד עתה\" וגו':"],
    [337,4,"כיון שנכנסו לארץ העמידו המשכן בגלגל ארבע עשרה שנה שכבשו ושחלקו. ומשם באו לשילה ובנו שם בית של אבנים ופרשו יריעות המשכן עליו ולא היתה שם תקרה. ושס\"ט שנה עמד משכן שילה וכשמת עלי חרב ובאו לנב ובנו שם מקדש. וכשמת שמואל חרב ובאו לגבעון ובנו שם מקדש. ומגבעון באו לבית העולמים. וימי נב וגבעון שבע וחמשים שנה:"],
    [337,5,"כיון שנבנה המקדש בירושלים נאסרו כל המקומות כלן לבנות בהן בית לה׳ ולהקריב בהן קרבן. ואין שם בית לדורי הדורות אלא בירושלים בלבד ובהר המוריה שבה נאמר \"ויאמר דויד זה הוא בית ה׳ האלהים וזה מזבח לעלה לישראל\" ואומר \"זאת מנוחתי עדי עד\":"],
    [337,6,"בנין שבנה שלמה כבר מפרש במלכים. וכן בנין העתיד להבנות אף על פי שהוא כתוב ביחזקאל אינו מפרש ומבאר. ואנשי בית שני כשבנו בימי עזרא בנוהו כבנין שלמה ומעין דברים המפרשים ביחזקאל:"],
    [337,7,"ואלו הן הדברים שהן עקר בבנין הבית. עושין בו קדש וקדש הקדשים ויהיה לפני הקדש מקום אחד והוא הנקרא אולם. ושלשתן נקראין היכל. ועושין מחצה אחרת סביב להיכל רחוקה ממנו כעין קלעי החצר שהיו במדבר. וכל המקף במחיצה זו שהוא כעין חצר אהל מועד הוא הנקרא עזרה והכל נקרא מקדש:"],
    [337,8,"ועושין במקדש כלים. מזבח לעולה ולשאר הקרבנות. וכבש שעולים בו למזבח. ומקומו לפני האולם משוך לדרום. וכיור וכנו לקדש ממנו הכהנים ידיהם ורגליהם לעבודה. ומקומו בין האולם ולמזבח משוך לדרום שהוא שמאל הנכנס למקדש. ומזבח לקטרת ומנורה ושלחן ושלשתן בתוך הקדש לפני קדש הקדשים:"],
    [337,9,"המנורה בדרום משמאל הנכנס ושלחן מימין שעליו לחם הפנים. ושניהם בצד קדש הקדשים מבחוץ ומזבח הקטרת משוך מבין שניהם לחוץ. ועושין בתוך העזרה גבולין עד כאן לישראל עד כאן לכהנים. ובונים בה בתים לשאר צרכי המקדש כל בית מהם נקרא לשכה:"],
    [337,10,"כשבונין ההיכל והעזרה בונין באבנים גדולות. ואם לא מצאו אבנים בונין בלבנים. ואין מפצלין את אבני הבנין בהר הבית אלא מפצלין אותן ומסתתין אותן מבחוץ ואחר כך מכניסין אותן לבנין. שנאמר \"אבנים גדלות אבנים יקרות ליסד הבית אבני גזית\". ואומר \"ומקבות והגרזן כל כלי ברזל לא נשמע בבית בהבנתו\":"],
    [337,11,"ואין בונין בו עץ בולט כלל אלא או באבנים או בלבנים וסיד. ואין עושין אכסדרות של עץ בכל העזרה אלא של אבנים או לבנים:"],
    [337,12,"ומרצפין את כל העזרה באבנים יקרות. ואם נעקרה אבן אף על פי שהיא עומדת במקומה. הואיל ונתקלקלה פסולה ואסור לכהן העובד לעמד עליה בשעת העבודה עד שתקבע בארץ:"],
    [337,13,"ומצוה מן המבחר לחזק את הבנין ולהגביהו כפי כח הצבור שנאמר \"ולרומם את בית אלהינו\". ומפארין אותו ומיפין כפי כחן אם יכולין לטוח אותו בזהב ולהגדיל במעשיו הרי זה מצוה:"],
    [337,14,"אין בונין את המקדש בלילה שנאמר \"וביום הקים את המשכן\" ביום מקימין לא בלילה. ועוסקין בבנין מעלות השחר עד צאת הכוכבים. והכל חיבין לבנות ולסעד בעצמן ובממונם אנשים ונשים כמקדש המדבר. ואין מבטלין תינוקות של בית רבן לבנין. ואין בנין בית המקדש דוחה יום טוב:"],
    [337,15,"המזבח אין עושין אותו אלא בנין אבנים (גזית) וזה שנאמר בתורה \"מזבח אדמה תעשה לי\" שיהיה מחבר באדמה שלא יבנוהו לא על גבי כפין ולא על גבי מחלות. וזה שנאמר \"ואם מזבח אבנים\" מפי השמועה למדו שאינו רשות אלא חובה:"],
    [337,16,"כל אבן שנפגמה כדי שתחגר בה הצפרן כסכין של שחיטה הרי זו פסולה לכבש ולמזבח שנאמר \"אבנים שלמות תבנה את מזבח ה׳\". ומהיכן היו מביאין אבני מזבח מן בתולת הקרקע חופרין עד שמגיעין למקום הנכר שאינו מקום עבודה ובנין ומוציאין ממנו האבנים. או מן הים הגדול. ובונין מהן. וכן אבני ההיכל והעזרות שלמות היו:"],
    [337,17,"אבני היכל ועזרות שנפגמו או שנגממו פסולין ואין להן פדיון אלא נגנזים. כל אבן שנגע בה הברזל אף על פי שלא נפגמה פסולה לבנין המזבח ובנין הכבש שנאמר \"כי חרבך הנפת עליה ותחללה\". והבונה אבן שנגע בה ברזל במזבח או בכבש לוקה שנאמר \"לא תבנה אתהן גזית\". והבונה אבן פגום עובר בעשה:"],
    [337,18,"אבן שנפגמה או שנגע בה ברזל אחר שנבנית במזבח או בכבש אותה האבן פסולה והשאר כשרות. ומלבנין את המזבח פעמים בשנה בפסח ובחג. וכשמלבנין אותן מלבנין במפה. אבל לא בכפיס של ברזל שמא יגע באבן ויפסל:"],
    [337,19,"אין עושין מדרגות למזבח שנאמר \"לא תעלה במעלת על מזבחי\". אלא בונין כמו תל בדרומו של מזבח מתמעט ויורד מראש המזבח עד הארץ והוא הנקרא כבש. והעולה במעלות על המזבח לוקה. וכן הנותץ אבן אחת מן המזבח או מכל ההיכל או מבין האולם ולמזבח דרך השחתה לוקה שנאמר \"ונתצתם את מזבחתם\" וגו' \"לא תעשון כן לה׳ אלהיכם\":"],
    [337,20,"המנורה וכליה והשלחן וכליו ומזבח הקטרת וכל כלי שרת אין עושין אותן אלא מן המתכת בלבד. ואם עשאום של עץ או עצם או אבן או של זכוכית פסולין:"],
    [337,21,"היו הקהל עניים עושין אותן אפלו של בדיל ואם העשירו עושין אותן זהב אפלו המזרקות והשפודין והמגרפות של מזבח העולה והמדות אם יש כח בצבור עושין אותן של זהב אפלו שערי העזרה מחפין אותן זהב אם מצאה ידם:"],
    [337,22,"אין עושין כל הכלים מתחלתן אלא לשם הקדש. ואם נעשו מתחלתן להדיוט אין עושין אותן לגבוה. וכלי גבוה עד שלא נשתמש בהן גבוה רשאי להשתמש בהן הדיוט. ומשנשתמש בהן גבוה אסורין להדיוט. אבנים וקורות שחצבן מתחלה לבית הכנסת אין בונין אותן להר הבית:"],
    [337,24,"המזבח מקומו מכון ביותר. ואין משנין אותו ממקומו לעולם. שנאמר \"זה מזבח לעולה לישראל\". ובמקדש נעקד יצחק אבינו שנאמר \"ולך לך אל ארץ המריה\". ונאמר בדברי הימים \"ויחל שלמה לבנות את בית ה׳ בירושלים בהר המוריה אשר נראה לדויד אביהו אשר הכין במקום דויד בגרן ארנן היבוסי\":"],
    [337,25,"ומסרת ביד הכל שהמקום שבנה בו דוד ושלמה המזבח בגרן ארונה הוא המקום שבנה בו אברהם המזבח ועקד עליו יצחק. והוא המקום שבנה בו נח כשיצא מן התבה. והוא המזבח שהקריב עליו קין והבל. ובו הקריב אדם הראשון קרבן כשנברא ומשם נברא. אמרו חכמים אדם ממקום כפרתו נברא:"],
    [337,26,"מדות המזבח מכונות הרבה וצורתו ידועה איש מאיש. ומזבח שבנו בני הגולה כעין מזבח שעתיד להבנות עשוהו ואין להוסיף על מדתו ולא לגרע ממנה:"],
    [337,27,"ושלשה נביאים עלו עמהם מן הגולה. אחד העיד להן על מקום המזבח. ואחד העיד להן על מדותיו. ואחד העיד להן שמקריבין על המזבח הזה כל הקרבנות אף על פי שאין שם בית:"],
    [337,28,"מזבח שעשה משה ושעשה שלמה ושעשו בני הגולה ושעתיד להעשות כלן עשר אמות גבה כל אחד מהן. וזה הכתוב בתורה \"ושלש אמות קומתו\" מקום המערכה בלבד. ומזבח שעשו בני הגולה וכן העתיד להבנות מדת ארכו ורחבו ל\"ב אמות על ל\"ב אמות:"],
    [337,29,"עשר אמות של גבה המזבח מהן באמה בת חמשה טפחים ומהן באמה בת ששה טפחים. ושאר כל אמות הבנין באמה בת ששה טפחים. וגבה כל המזבח נ\"ח טפחים:"],
    [337,30,"וכך היתה מדתו וצורתו. עלה חמשה טפחים וכנס חמשה טפחים זהו יסוד. נמצא רחב שלשים אמה ושני טפחים על רחב שלשים אמה ושני טפחים. עלה שלשים טפחים וכנס חמשה טפחים זהו סובב [עלה י\"ח טפחים זהו מקום המערכה] נמצא רחבו שמונה ועשרים אמה וארבעה טפחים על שמונה ועשרים אמה וארבעה טפחים [עלה י\"ח טפחים וכונס לקרן זוית של הי\"ח בנין חלול מרבע לכל ארבע קרנות] ומקום הקרנות אמה מזה ואמה מזה סביב. וכן מקום רגלי הכהנים אמה סביב. נמצא מקום המערכה רחבו עשרים וארבע אמות וארבעה טפחים על עשרים וארבע אמות וארבעה טפחים:"],
    [337,31,"גבה כל קרן וקרן חמשה טפחים. ורבוע כל קרן אמה על אמה. וארבע הקרנות חלולות היו מתוכן. וגבה מקום המערכה י\"ח טפחים. נמצא חצי גבה המזבח כ\"ט טפחים מסוף הסובב ולמטה:"],
    [337,32,"וחוט של סקרה היה חוגר באמצע המזבח [כששה טפחים מסוף הסובב ולמטה] להבדיל בין דמים העליונים לדמים התחתונים. ונמצא גבהו מן הארץ עד מקום המערכה תשע אמות פחות טפח:"],
    [337,33,"יסוד המזבח לא היה מקיף מארבע רוחותיו כמו הסובב. אלא היה היסוד משוך כנגד כל רוח צפון ומערבי ואוכל בדרום אמה אחת ובמזרח אמה אחת. וקרן דרומית מזרחית לא היה לה יסוד:"],
    [337,34,"ובקרן מערבית דרומית היו שני נקבים כמין שני חטמין דקין. והן הנקראין שיתין שהדמים יורדין בהן ומתערבין באותה הקרן באמה ויוצאין לנחל קדרון:"],
    [337,35,"ולמטה ברצפה באותו הקרן היה מקום אמה על אמה וטבלא של שיש וטבעת קבועה בה שבו יורדין לשיתין ומנקין אותו:"],
    [337,36,"וכבש היה בנוי לדרומו של מזבח. ארכו שלשים ושתים אמה על רחב ט\"ז אמה והיה אוכל בארץ שלשים אמה מצד המזבח. ופורח ממנה אמה על היסוד ואמה על הסובב. ואויר מעט היה מפסיק בין הכבש למזבח כדי לתן האיברים למזבח בזריקה. וגבה הכבש תשע אמות פחות שתות עד כנגד המערכה:"],
    [337,37,"ושני כבשים קטנים יוצאים ממנו שבהם פונים ליסוד ולסובב ומבדלין מן המזבח כמלא נימא. וחלון היתה במערבו של כבש אמה על אמה ורבובה היתה נקראת. שבה נותנין פסולי חטאת העוף עד שתעבר צורתה ותצא לבית השרפה:"],
    [337,38,"ושני שלחנות היו במערב הכבש אחד של שיש שנותנין עליו את האיברים ואחד של כסף שנותנין עליו כלי השרת:"],
    [337,39,"כשבונין המזבח בונין אותו כלו אטום כמין עמוד ואין עושין בו חלל כלל. אלא מביא אבנים שלמות גדולות וקטנות ומביא סיד וזפת וקוניא וממחה ושופך לתוך מלבן גדול כמדתו ובונה ועולה. ונותן בתוך הבנין גוף של עץ או אבן בקרן דרומית מזרחית כמדת היסוד. וכן נותן בתוך כל קרן וקרן עד שישלים הבנין ויסיר הגופים שבתוך הבנין כדי שתשאר קרן דרומית מזרחית בלא יסוד וישארו הקרנות חלולין:"],
    [337,40,"ארבע קרנות של מזבח ויסודו ורבועו מעכבין. וכל מזבח שאין לו קרן יסוד וכבש ורבוע הרי הוא פסול שארבעתן מעכבין. אבל מדת ארכו ומדת רחבו ומדת קומתו אינן מעכבין. והוא שלא יפחת מאמה על אמה ברום שלש אמות כשעור מקום המערכה של מזבח מדבר:"],
    [337,41,"מזבח שנפגם מבנינו אם נפגם מבנינו טפח פסול פחות מטפח כשר והוא שלא יהיה בנשאר אבן פגומה:"],
    [337,43,"המנורה מפרשת צורתה בתורה. וארבעה גביעים ושני כפתורים ושני פרחים היו בקנה המנורה שנאמר \"ובמנרה ארבעה גבעים משקדים כפתריה ופרחיה\". ועוד פרח שלישי היה סמוך לירכה של מנורה שנאמר \"עד ירכה עד פרחה\":"],
    [337,44,"ושלש רגלים היו לה. ושלשה כפתורים אחרים היו בקנה המנורה שמהן יוצאים ששת הקנים. שלשה מצד זה ושלשה מצד זה. ובכל קנה וקנה מהן שלשה גביעים וכפתור ופרח. והכל משקדים כמו שקדים בעשיתן:"],
    [337,45,"נמצאו כל הגביעים שנים ועשרים. והפרחים תשעה. והכפתורים אחד עשר. וכלן מעכבין זה את זה ואפלו חסר אחד מן השנים וארבעים מעכב את כלן:"],
    [337,46,"במה דברים אמורים בשעשאוה זהב. אבל שאר מיני מתכות אין עושין בה גביעים כפתורים ופרחים. וכן מנורה הבאה זהב תהיה כלה ככר עם נרותיה ותהיה כלה מקשה מן העשתות. ושל שאר מיני מתכות אין מקפידין על משקלה. ואם היתה חלולה כשרה:"],
    [337,47,"ואין עושין אותה לעולם מן הגרוטאות בין שהיתה של זהב בין שהיתה של שאר מיני מתכות:"],
    [337,48,"המלקחים והמחתות וכלי השמן אינן מכלל הככר שהרי נאמר במנורה \"זהב טהור\" וחזר ואמר ומלקחיה ומחתתיה זהב טהור. ולא נאמר נרותיה זהב טהור מפני שהנרות קבועין במנורה והם מכלל הככר:"],
    [337,49,"שבעת קני המנורה מעכבין זה את זה. ושבעת נרותיה מעכבין זה את זה בין שהיתה של זהב בין שהיתה של שאר מיני מתכות. וכל הנרות קבועים בקנים:"],
    [337,50,"ששת הנרות הקבועים בששת הקנים היוצאים מן המנורה כלן פניהם לנר האמצעי שעל קני המנורה וזה הנר האמצעי פניו כנגד קדש הקדשים והוא הנקרא נר מערבי:"],
    [337,51,"הגביעים דומין לכוסות אלכסנדריאה שפיהן רחב ושוליהן קצר. והכפתורים כמין תפוחים כרותיים שהן ארכין מעט כביצה ששני ראשיה כדין. והפרחים כמו פרחי העמודים שהן כמין קערה ושפתה כפולה לחוץ:"],
    [337,52,"גבה המנורה היה שמונה עשר טפח. הרגלים והפרח שלשה טפחים. ושני טפחים חלק. וטפח שבו גביע כפתור ופרח. וטפחים חלק. וטפח כפתור ושני קנים יוצאין ממנו אחד הילך ואחד הילך ונמשכים ועולין כנגד גבה המנורה. וטפח חלק. וטפח כפתור ושני קנים יוצאים ממנו אחד הילך ואחד הילך ונמשכין ועולין כנגד גבה המנורה. וטפח חלק. וטפח כפתור ושני קנים יוצאים ממנו אחד הילך ואחד הילך ונמשכין ועולין כנגד גבה המנורה. וטפחים חלק. נשתירו שלשה טפחים שבהן שלשה גביעים כפתור ופרח:"],
    [337,53,"ואבן היתה לפני המנורה ובה שלש מעלות שעליה כהן עומד ומיטיב את הנרות ומניח עליה כלי שמנה ומלקחיה ומחתותיה בשעת הטבה:"],
    [337,54,"השלחן היה ארכו שנים עשר טפח ורחבו ששה טפחים. והיה מנח ארכו לארך הבית ורחבו לרחב הבית. וכן שאר כל הכלים שבמקדש ארכן לארכו של בית ורחבן לרחב הבית חוץ מן הארון שהיה ארכו לרחב הבית. וכן נרות המנורה כנגד רחב הבית בין הצפון ובין הדרום:"],
    [337,55,"ארבעה סניפין של זהב היו לשלחן מפצלין בראשיהן שהיו סומכין בהן שתי המערכות של לחם הפנים. שנים מסדר זה. ושנים מסדר זה. והם הנאמרים בתורה \"וקשותיו\":"],
    [337,56,"ושמונה ועשרים קנים של זהב כל אחד מהן כחצי קנה חלול היו לו. ארבעה עשר לסדר זה וארבעה עשר לסדר זה. והם הנקראים \"מנקיותיו\". ושני הבזיכין שמניחין בהן הלבונה על השלחן בצד המערכות הן הנקראין \"כפותיו\". והדפוסין שעושין בהם לחם הפנים הם הנקראים \"קערותיו\":"],
    [337,57,"אלו הארבעה עשר קנים נותן החלה הראשונה על עצמו של שלחן ונותן בין ראשונה ושניה שלשה קנים. וכן בין כל חלה וחלה שלשה קנים. ובין ששית וחמישית שני קנים בלבד לפי שאין על הששית אחרת. נמצאו ארבעה עשר בכל מערכה ומערכה:"],
    [337,58,"ושני שלחנות היו באולם מבפנים על פתח הבית. אחד של שיש נותנין עליו לחם הפנים בכניסתו. ואחד של זהב נותנין עליו לחם ביציאתו. שמעלין בקדש ולא מורידין:"],
    [337,59,"מזבח הקטרת היה מרבע אמה על אמה. והוא נתון בהיכל מכון בין הצפון לדרום משוך בין השלחן והמנורה לחוץ. ושלשתן היו מנחין משליש ההיכל ולפנים כנגד הפרכת המבדיל בין הקדש ובין קדש הקדשים:"],
    [337,60,"הכיור היו לו שנים עשר דד כדי שיהיו כל הכהנים העוסקים בתמיד מקדשים ממנו כאחד. ומוכני עשו לו שיהיו בה המים תמיד. והיא חל כדי שלא יהיו המים שבה נפסלין בלינה שהכיור מכלי הקדש ומקדש וכל דבר שיתקדש בכלי קדש אם לן נפסל:"],
    [337,62,"אבן היתה בקדש הקדשים במערבו שעליה היה הארון מנח. ולפניו צנצנת המן ומטה אהרן. ובעת שבנה שלמה את הבית וידע שסופו לחרב בנה בו מקום לגנז בו הארון למטה במטמוניות עמקות ועקלקלות ויאשיהו המלך צוה וגנזו במקום שבנה שלמה שנאמר \"ויאמר ללוים המבינים לכל ישראל הקדושים לה׳ תנו את ארון הקדש בבית אשר בנה שלמה בן דויד מלך ישראל אין לכם משא בכתף עתה עבדו את ה׳ אלהיכם\" וגו'. ונגנז עמו מטה אהרן והצנצנת ושמן המשחה וכל אלו לא חזרו בבית שני. ואף אורים ותמים שהיו בבית שני לא היו משיבין ברוח הקדש. ולא היו נשאלין בהן שנאמר \"עד עמד כהן לאורים ותמים\". ולא היו עושין אותן אלא להשלים שמונה בגדים לכהן גדול כדי שלא יהא מחסר בגדים:"],
    [337,63,"בבית ראשון היה כתל מבדיל בין הקדש ובין קדש הקדשים עביו אמה. וכיון שבנו הבית שני נסתפק להם אם עבי הכתל היה ממדת הקדש או ממדת קדש הקדשים לפיכך עשו קדש הקדשים עביו עשרים אמה תמימות ועשו הקדש ארבעים אמה תמימות והניחו אמה יתרה בין הקדש ובין קדש הקדשים ולא בנו כתל בבית שני אלא עשו שתי פרוכות אחת מצד קדש הקדשים ואחת מצד הקדש וביניהן אמה כנגד עבי הכתל שהיה בראשון. אבל במקדש ראשון לא היתה שם אלא פרכת אחת בלבד שנאמר \"והבדילה הפרכת לכם\" וגו':"],
    [337,64,"ההיכל שבנו בני גולה היה מאה אמה על מאה אמה על רום מאה. וכן היתה מדת רומו. בנו גבה שש אמות אטום סתום כמו יסוד לו. ורום כתלי הבית ארבעים אמה ורום הכיור שבתקרה אמה ועל גביו גבה שתי אמות פנוי שיכנס בו הדלף והוא הנקרא בית דילפא. ועבי התקרה שעל גבי בית דילפא אמה. ומעזיבה גבה אמה. ועליה בנויה על גביו גבה כתליה ארבעים אמה. ובגגה גבה אמה כיור ואמתים גבה בית דילפא ואמה תקרה ואמה מעזיבה וגבה המעקה שלש אמות וטס של ברזל כמו סיף גבהו אמה על גבי המעקה סביב כדי שלא ינוחו עליו העופות והוא הנקרא כלה עורב. הרי הכל מאה אמה:"],
    [337,65,"מן המערב למזרח מאה אמה וזהו חשבונן. ארבעה כתלים זה לפנים מזה וביניהן שלשה מקומות פנויין. בין הכתל המערבי ובין הכתל שלפנים ממנו חמש אמות ובין כתל שני ושלישי שש אמות ובין כתל שלישי ורביעי שש אמות. ואלו המדות הן של עבי הכתל עם המקום הפנוי שבין שני כתלים. וארך קדש הקדשים עשרים אמה. ובין שתי הפרוכות המבדילות בינו ובין הקדש אמה. וארך הקדש ארבעים אמה. ועבי הכתל המזרחי שבו השער שש אמות והאולם אחת עשרה אמה. ועבי כתל האולם חמש אמות. נמצא הכל מאה אמה:"],
    [337,66,"מן הצפון לדרום מאה אמה. עבי כתל האולם חמש אמות. ומכתל אולם עד כתל הקדש עשר אמות. וכתלי הקדש ששה כתלים זה לפנים מזה וביניהן חמשה מקומות פנויין. בין כתל חיצון ובין השני חמש אמות. ובין שני ושלישי שלש אמות. וחמש בין שלישי ורביעי. ובין רביעי וחמישי שש. ובין חמישי וכתל הפנימי שש. נמצא הכל ארבעים אמה מצד זה וארבעים אמה מצד שכנגדו ורחב הבית מבפנים עשרים. הרי מאה אמה:"],
    [337,67,"הפשפש והוא שער הקטן. ושני פשפשין היו להיכל מצדי השער הגדול שבאמצע. אחד בצפון ואחד בדרום. שבדרום לא נכנס בו אדם מעולם ועליו הוא מפרש על ידי יחזקאל \"השער הזה סגור יהיה לא יפתח\". ושבצפון בו נכנסין. ומהלך בין שני הכתלים עד שמגיע למקום פתוח לקדש משמאלו ונכנס לתוך ההיכל ומהלך עד שער הגדול ופותחו:"],
    [337,68,"השער הגדול היה רחבו עשר אמות וגבהו עשרים אמה. וארבע דלתות היו לו שתים בפנים ושתים בחוץ. החיצונות נפתחות לתוך הפתח לכסות עביו של כתל והפנימיות נפתחות לתוך הבית לכסות אחורי הדלתות:"],
    [337,69,"פתחו של אולם היה גבוה ארבעים אמה ורחב עשרים. ולא היה לו שערים. וחמש מלתריות של מילא היו על גבי פתחו מלמעלה. התחתונה עודפת על הפתח אמה מזה ואמה מזה. וכל אחת מחמשתן עודפת על שלמטה ממנה אמה מזה ואמה מזה. נמצאת העליונה שלשים אמה. ונדבך של אבנים היה בין כל אחת ואחת:"],
    [337,70,"ההיכל היה בנינו רחב מלפניו וצר מאחוריו כמו ארי. ויציעים היו מקיפין לבית כלו מסביב חוץ לכתל המסבה. ויציע התחתונה חמש ורבד על גבה שש ויציע אמצעית שש ורבד על גבה שבע והעליונה שבע שנאמר \"היציע התחתנה\" וגו'. וכן היו השלש יציעים מקיפים לבית משלשה רוחותיו וכן סביב לכתלי האולם מלמטה עד למעלה כך היו אמה אחת חלק ורבד שלש אמות. ואמה חלק ורבד שלש אמות עד למעלה. ונמצאו הרבדין מקפין לכתלים. רחב כל רבד שלש אמות עד למעלה. ובין כל רבד ורבד אמה. ורבד העליון היה רחבו ארבע אמות:"],
    [337,71,"כל אלו המקומות הפנויים שבין הכתלים הם הנקראים תאים. נמצאו התאים המקפין למקדש חמשה מן הצפון וחמשה מן הדרום ושלשה מן המערב. ושלש דיוטות היו דיוטא על גבי דיוטא. נמצאו ט\"ו תאים בדרום חמשה על גבי חמשה וחמשה על גביהן וכן בצפון חמשה עשר. ושמונה תאים היו במערב שלשה על גבי שלשה ושנים על גביהן בדיוטא אחת הכל ל\"ח תאים:"],
    [337,72,"שלשה פתחים היו לכל אחד ואחד מן התאים. אחד לתא מן הימין. ואחד לתא מן השמאל. ואחד לתא שעל גביו. ובקרן מזרחית צפונית בתא שבדיוטא האמצעית היו חמשה פתחים. אחד לתא מימין. ואחד לתא שעל גביו. ואחד למסבה. ואחד לתא שיש בו הפשפש. ואחד להיכל:"],
    [337,73,"ומסבה היתה עולה מקרן מזרחית צפונית לקרן צפונית מערבית שבה היו עולין לגגות התאים. היה עולה במסבה ופניו למערב הלך את כל פני הצפון עד שהוא מגיע למערב. הגיע למערב הפך פניו לדרום הלך את כל פני המערב עד שהוא מגיע לדרום. הגיע לדרום הפך פניו למזרח והיה מהלך לדרום עד שהוא מגיע לפתחה של עליה שפתחה של עליה היה פתוח לדרום:"],
    [337,74,"ובפתחה של עליה היו שתי כלונסות של ארז שבהן עולין לגגה של עליה. וראשי פספסין היו מבדילין בעליה בין גג הקדש לגג קדש הקדשים. ולולין היו פתוחין בעליה לבית קדש הקדשים שבהן משלשלין את האמנין בתבות כדי שלא יזונו עיניהם מבית קדש הקדשים. ופעם אחת בשנה מפסח לפסח מלבנין את ההיכל:"],
    [337,76,"הר הבית והוא הר המוריה היה חמש מאות אמה על חמש מאות אמה והיה מקף חומה. וכפין על גבי כפין היו בנויות מתחתיו. מפני אהל הטמאה. וכלו היה מקרה סטיו לפנים מסטיו:"],
    [337,77,"וחמשה שערים היו לו. אחד מן המערב ואחד מן המזרח ואחד מן הצפון ושנים מן הדרום. רחב כל שער עשר אמות וגבהו עשרים. ויש להם דלתות:"],
    [337,78,"לפנים ממנו סורג מקיף סביב גבהו עשרה טפחים ולפנים מן הסורג החיל [גבהו] עשר אמות. ועליו הוא אומר בקינות \"ויאבל חל וחומה\" זו חומת העזרה:"],
    [337,79,"לפנים מן החיל העזרה. וכל העזרה היתה ארך קפ\"ז על רחב קל\"ה. ושבעה שערים היו לה. שלשה מן הצפון הסמוכין למערב. ושלשה מן הדרום סמוכין למערב. ואחד במזרח מכון כנגד בית קדש הקדשים באמצע:"],
    [337,80,"כל שער מהן היה רחבו עשר אמות וגבהו עשרים אמה. והיו לו דלתות מחפות זהב. חוץ משער מזרחי שהיה מצפה נחשת דומה לזהב. ושער זה הוא הנקרא שער העליון והוא שער ניקנור:"],
    [337,81,"העזרה לא היתה מכונת באמצע הר הבית. אלא רחוקה מדרום הר הבית יתר מכל הרוחות וקרובה למערב יתר מכל הרוחות. ובינה ובין הצפון יתר ממה שבינה ובין המערב. ובינה ובין המזרח יתר ממה שבינה ובין הצפון:"],
    [337,82,"ולפני העזרה במזרח היתה עזרת הנשים. והיא היתה ארך מאה אמה וחמשה ושלשים על רחב קל\"ה. וארבע לשכות היו בארבע מקצעותיה של ארבעים ארבעים אמה ולא היו מקרות וכן עתידין להיות:"],
    [337,83,"ומה הם משמשות. דרומית מזרחית לשכת הנזירים ששם מבשלין את שלמיהם ומגלחין את שערם. מזרחית צפונית לשכת דיר העצים ששם כהנים בעלי מומין מתליעים בעצים. שכל עץ שנמצא בו תולעת פסול. צפונית מערבית לשכת המצרעים. מערבית דרומית בה היו נותנין יין ושמן והיא היתה נקראת לשכת בית שמניא:"],
    [337,84,"עזרת הנשים היתה מקפת גזוזטרא כדי שיהיו הנשים רואות מלמעלן והאנשים מלמטן כדי שלא יהיו מערבבין. ובית גדול היה בצד העזרה בצפונה מבחוץ בין העזרה והחיל והיה בנוי כפה ומקף רבדין של אבן והוא היה נקרא בית המוקד. ושני פתחים היו לו אחד פתוח לעזרה ואחד פתוח לחיל:"],
    [337,85,"וארבע לשכות היו בו. שתים קדש ושתים חל. וראשי פספסין מבדילין בין הקדש והחל. ומה היו משמשות מערבית דרומית לשכת הטלאים. ודרומית מזרחית לשכת עושי לחם הפנים. מזרחית צפונית בה גנזו בית חשמוני אבני מזבח ששקצום מלכי יון. צפונית מערבית בה יורדין לבית הטבילה:"],
    [337,86,"היורד לבית הטבילה מלשכה זו היה הולך במסבה ההולכת תחת המקדש כלו והנרות דולקות מכאן ומכאן עד שמגיע לבית הטבילה. ומדורה היתה שם. ובית הכסא של כבוד. וזהו כבודו, מצאו נעול בידוע שיש שם אדם:"],
    [337,87,"ארך העזרה מן המזרח למערב קפ\"ז וזהו חשבונן. מכתל מערבי של עזרה עד כתל ההיכל אחת עשרה אמה. וארך ההיכל כלו מאה אמה. בין האולם ולמזבח שתים ועשרים. המזבח שתים ושלשים. מקום דריסת רגלי הכהנים והוא הנקרא עזרת כהנים אחת עשרה אמה. מקום דריסת רגלי ישראל והוא הנקרא עזרת ישראל אחת עשרה אמה:"],
    [337,88,"ורחב העזרה מן הצפון לדרום מאה ושלשים וחמש וזהו חשבונן. מכתל צפוני עד בית המטבחים שמונה אמות. בית המטבחים י\"ב אמות ומחצה. ושם תולין ומפשיטין את הקדשים בצדו:"],
    [337,89,"מקום השלחנות שמונה אמות ובו שלחנות של שיש שמניחין עליהן הנתחים ומדיחין את הבשר לבשלו. ושמונה שלחנות היו. ובצד מקום השלחנות מקום הטבעות כ\"ד אמה. ושם שוחטין את הקדשים:"],
    [337,90,"ובין מקום הטבעות והמזבח שמונה אמות והמזבח ל\"ב. והכבש שלשים. ובין הכבש ולכתל דרומי י\"ב אמה ומחצה. מכתל צפוני של עזרה עד כתל המזבח שהוא רחב ששים ומחצה. וכנגדו מכתל האולם עד כתל מזרחי של עזרה שהוא ארך שש ושבעים:"],
    [337,91,"כל המרבע הזה הוא הנקרא צפון הוא המקום ששוחטין בו קדשי קדשים:"],
    [337,92,"שמונה לשכות היו בעזרת ישראל. שלש בצפון. ושלש בדרום. שבדרום לשכת המלח. לשכת הפרוה. לשכת המדיחין. לשכת המלח שם נותנין מלח לקרבן. לשכת הפרוה שם מולחין עורות הקדשים. ועל גגה היתה בית טבילה לכהן גדול ביום הכפורים. לשכת המדיחין שם היו מדיחין קרבי הקדשים ומשם מסבה עולה לגג בית הפרוה. והשלש שבצפון לשכת הגזית. לשכת הגולה. לשכת העץ. לשכת הגזית שבה סנהדרי גדולה יושבת. וחציה היה קדש וחציה היה חל. ולה שני פתחים אחד לקדש ואחד לחל ובחצי של חל היו הסנהדרין יושבין. לשכת הגולה שם היתה בור שממלאין ממנו בגולה ומשם מספקין מים לכל העזרה. ולשכת העץ היתה אחורי שתיהן והיא היתה לשכת כהן גדול והיא הנקראת לשכת פרהדרין. וגג שלשתן שוה. ושתי לשכות אחרות היו שם בעזרת ישראל. אחת מימין שער מזרחי והוא לשכת פינחס המלביש. ואחד משמאלו והוא לשכת עושה חביתין:"],
    [337,94,"המקדש כלו לא היה במישור אלא במעלה ההר. כשאדם נכנס משער מזרחי של הר הבית מהלך עד סוף החיל בשוה. ועולה מן החיל לעזרת הנשים בשתים עשרה מעלות רום כל מעלה חצי אמה ושלחה חצי אמה:"],
    [337,95,"ומהלך כל עזרת הנשים בשוה. ועולה ממנה לעזרת ישראל שהוא תחלת העזרה בחמש עשרה מעלות. רום כל מעלה חצי אמה ושלחה חצי אמה:"],
    [337,96,"ומהלך כל עזרת ישראל בשוה ועולה ממנו לעזרת הכהנים במעלה גבוהה אמה ועליה דוכן יש בו שלש מעלות. רום כל מעלה חצי אמה ושלחה חצי אמה. נמצאת עזרת הכהנים גבוהה על של ישראל שתי אמות ומחצה:"],
    [337,97,"ומהלך כל עזרת הכהנים והמזבח. ובין האולם ולמזבח בשוה. ועולה משם לאולם בשתים עשרה מעלות. רום כל מעלה חצי אמה ושלחה חצי אמה והאולם וההיכל כלו בשוה:"],
    [337,98,"נמצא גבה קרקע ההיכל על קרקע שער המזרח של הר הבית שתים ועשרים אמות. וגבה שער הר הבית עשרים אמה. לפיכך העומד כנגד שער המזרח אינו רואה פתח ההיכל. ומפני זה עשו כתל שעל גבי שער זה נמוך. כדי שיהא כהן העומד בהר המשחה רואה פתח ההיכל בשעה שמזה מדם הפרה נכח ההיכל:"],
    [337,99,"ולשכות היו שם תחת עזרת ישראל פתוחות לעזרת הנשים. ששם הלוים נותנין הכנורות והנבלים והמצלתים וכל כלי השיר. ועל הדוכן העולה מעזרת ישראל לעזרת הכהנים היו הלוים עומדים בשעה שאומרים שירה על הקרבן:"],
    [337,100,"הלשכות הבנויות בקדש ופתוחות לחל אם היו גגותיהן שוין עם קרקע העזרה תוכן חל וגגותיהן קדש ואם אינן שוין אף גגותיהן חל שהגגות והעליות לא נתקדשו. לפיכך גגים אלו אין אוכלין שם קדשי קדשים ולא שוחטין קדשים קלים:"],
    [337,101,"היו בנויות לחל ופתוחות לקדש תוכן קדש לאכילת קדשי קדשים אבל אין שוחטין שם קדשים קלים והנכנס לשם בטמאה פטור. וגגותיהן חל לכל דבר:"],
    [337,102,"המחלות הפתוחות לעזרה קדש והפתוחות להר הבית חל. החלונות ועבי החומה כלפנים בין לאכילת קדשי קדשים בין לטמאה:"],
    [337,103,"בית דין שרצו להוסיף על ירושלים או להוסיף על העזרה מוסיפין. ויש להם למשך העזרה עד המקום שירצו מהר הבית ולמשך חומת ירושלים עד מקום שירצו:"],
    [337,104,"אין מוסיפין על העיר או על העזרות אלא על פי המלך ועל פי נביא ובאורים ותמים ועל פי סנהדרין של שבעים ואחד זקנים שנאמר \"ככל אשר אני מראה אותך\" וכן תעשו לדורות. ומשה רבנו מלך היה:"],
    [337,105,"וכיצד מוסיפין על העיר. עושין בית דין שתי תודות ולוקחין לחם חמץ שבהם והולכים בית דין אחר שתי התודות ושתי התודות זו אחר זו ועומדין בכנורות ובנבלים ובצלצל על כל פנה ופנה ועל כל אבן (ואבן) שבירושלים ואומר \"ארוממך ה׳ כי דליתני\" וגו'. עד שמגיעין לסוף המקום שמקדשין אותו ועומדין שם. ואוכלים שם לחם תודה אחת משתי התודות והשניה נשרפת. ועל פי הנביא שורפין את זו ואוכלין את זו:"],
    [337,106,"וכן אם הוסיפו על העזרה מקדשין אותה בשירי המנחה. מה ירושלים התודה שנאכלת בה מקדשתה אף העזרה שירי המנחות שאין נאכלין אלא בה הן שמקדשין אותה בהן. ואוכלין אותן בסוף המקום שקדשו:"],
    [337,107,"כל מקום שלא נעשה בכל אלו וכסדר הזה אין קדוש גמור. וזה שעשה עזרא שתי תודות זכרון הוא שעשה לא במעשיו נתקדש המקום שלא היה שם לא מלך ולא אורים ותמים. ובמה נתקדשה בקדשה ראשונה שקדשה שלמה שהוא קדש העזרה וירושלים לשעתן וקדשן לעתיד לבוא:"],
    [337,108,"לפיכך מקריבין הקרבנות כלן אף על פי שאין שם בית בנוי. ואוכלין קדשי קדשים בכל העזרה אף על פי שהיא חרבה ואינה מקפת במחצה ואוכלין קדשים קלים ומעשר שני בכל ירושלים אף על פי שאין שם חומות שהקדשה ראשונה קדשה לשעתה וקדשה לעתיד לבוא:"],
    [337,109,"ולמה אני אומר במקדש וירושלים קדשה ראשונה קדשה לעתיד לבוא. ובקדשת שאר ארץ ישראל לענין שביעית ומעשרות וכיוצא בהן לא קדשה לעתיד לבוא. לפי שקדשת המקדש וירושלים מפני השכינה ושכינה אינה בטלה. והרי הוא אומר \"והשמותי את מקדשיכם\" ואמרו חכמים אף על פי ששוממין בקדשתן הן עומדים אבל חיוב הארץ בשביעית ובמעשרות אינו אלא מפני שהוא כבוש רבים וכיון שנלקחה הארץ מידיהם בטל הכבוש ונפטרה מן התורה ממעשרות ומשביעית שהרי אינה מן ארץ ישראל. וכיון שעלה עזרא וקדשה לא קדשה בכבוש אלא בחזקה שהחזיקו בה ולפיכך כל מקום שהחזיקו בה עולי בבל ונתקדש בקדשת עזרא השניה הוא מקדש היום ואף על פי שנלקח הארץ ממנו וחיב בשביעית ובמעשרות על הדרך שבארנו בהלכות תרומה:"],
    [337,111,"מצות עשה ליראה מן המקדש שנאמר \"ומקדשי תיראו\". ולא מן המקדש אתה ירא אלא ממי שצוה על יראתו:"],
    [337,112,"ואי זו היא יראתו לא יכנס אדם להר הבית במקלו או במנעל שברגליו או באפנדתו או באבק שעל רגליו או במעות הצרורין לו בסדינו ואין צריך לומר שאסור לרק בכל הר הבית אלא אם נזדמן לו רק מבליעו בכסותו. ולא יעשה הר הבית דרך שיכנס מפתח זו ויצא מפתח שכנגדה כדי לקצר הדרך אלא יקיפו מבחוץ. ולא יכנס לו אלא לדבר מצוה:"],
    [337,113,"וכל הנכנסין להר הבית נכנסין דרך ימין ומקיפין ויוצאין דרך שמאל חוץ ממי שארעו דבר שהוא מקיף על השמאל. לפיכך היו שואלין לו מה לך מקיף על השמאל. שאני אבל. השוכן בבית הזה ינחמך. שאני מנדה. השוכן בבית הזה יתן בלבבך ותשמע לדברי חבריך ויקרבוך:"],
    [337,114,"כל שהשלים עבודה ונסתלק לו אינו יוצא ואחוריו להיכל אלא מהלך אחורנית מעט מעט ומהלך בנחת על צדו עד שיצא מן העזרה. וכן אנשי משמר ואנשי מעמד ולוים מדוכנן כך הם יוצאין מן המקדש כמי שפוסע אחר תפלה לאחוריו. כל זה ליראה מן המקדש:"],
    [337,115,"לא יקל אדם את ראשו כנגד שער מזרחי של עזרה שהוא שער ניקנור. מפני שהוא מכון כנגד בית קדש הקדשים. וכל הנכנס לעזרה יהלך בנחת במקום שמתר לו להכנס לשם. ויראה עצמו שהוא עומד לפני ה׳ כמו שנאמר \"והיו עיני ולבי שם כל הימים\". ומהלך באימה וביראה ורעדה שנאמר \"בבית אלהים נהלך ברגש\":"],
    [337,116,"ואסור לכל אדם לישב בכל העזרה ואין ישיבה בעזרה אלא למלכי בית דוד בלבד שנאמר \"ויבא המלך דוד וישב לפני ה׳\". והסנהדרין שהיו יושבין בלשכת הגזית לא היו יושבין אלא בחציה של חל:"],
    [337,117,"אף על פי שהמקדש היום חרב בעונותינו חיב אדם במוראו כמו שהיה נוהג בו בבנינו. לא יכנס אלא למקום שמתר להכנס לשם ולא ישב בעזרה ולא יקל ראשו כנגד שער המזרח שנאמר \"את שבתתי תשמרו ומקדשי תיראו\". מה שמירת שבת לעולם אף מורא מקדש לעולם שאף על פי שחרב בקדשתו עומד:"],
    [337,118,"בזמן שהמקדש בנוי אסור לו לאדם להקל את ראשו מן הצופים שהוא חוץ לירושלים ולפנים. והוא שיהיה רואה את המקדש. ולא יהיה גדר מפסיק בינו ובין המקדש:"],
    [337,119,"אסור לאדם לעולם שיפנה או שיישן בין מזרח למערב. ואין צריך לומר שאין קובעין בית הכסא בין מזרח למערב בכל מקום מפני שההיכל במערב. לפיכך לא יפנה למערב ולא למזרח מפני שהוא כנגד המערב. אלא בין צפון לדרום נפנים וישנים. וכל המטיל מים מן הצופים ולפנים לא ישב ופניו כלפי הקדש אלא לצפון או לדרום או יסלק הקדש לצדדין:"],
    [337,120,"ואסור לאדם שיעשה בית תבנית היכל. אכסדרא תבנית אולם. חצר כנגד העזרה. שלחן בצורת שלחן. ומנורה בצורת מנורה. אבל עושה הוא מנורה של חמשה קנים או של שמונה קנים או מנורה שאינה של מתכת אף על פי שיש לה שבעה קנים:"],
    [337,121,"שלשה מחנות היו במדבר. מחנה ישראל והוא ארבע מחנות. ומחנה לויה שנאמר בה \"וסביב למשכן יחנו\". ומחנה שכינה והוא מפתח חצר אהל מועד ולפנים. וכנגדן לדורות. מפתח ירושלים עד הר הבית כמחנה ישראל. ומפתח הר הבית עד פתח העזרה שהוא שער ניקנור כמחנה לויה. ומפתח העזרה ולפנים מחנה שכינה. והחיל ועזרת הנשים מעלה יתרה בבית עולמים:"],
    [337,122,"כל ארץ ישראל מקדשת מכל הארצות. ומה היא קדשתה שמביאין ממנה העמר ושתי הלחם והבכורים מה שאין מביאין כן משאר ארצות:"],
    [337,123,"עשר קדשות הן בארץ ישראל וזו למעלה מזו. עירות המקפות חומה מקדשות משאר הארץ שמשלחין מתוכן את המצרעים ואין קוברין בתוכן מת עד שירצו שבעה טובי העיר או כל אנשי העיר. ואם יצא המת חוץ לעיר אין מחזירין אותו לתוכה אף על פי שרצו כלן להחזירו. רצו בני העיר להוציא הקבר מן המדינה מפנין אותו. וכל הקברות מפנין חוץ מקבר נביא או מלך. קבר שהקיפתו העיר בין מארבע רוחותיו בין משתי רוחות זו כנגד זו אם היתה בינו ובין העיר יתר מחמשים אמה לכאן וחמשים לכאן אין מפנין אותו עד שירצו כלן. פחות מכאן מפנין אותו:"],
    [337,124,"ירושלים מקדשת משאר העירות המקפות חומה. שאוכלין קדשים קלים ומעשר שני לפנים מחומתה. ואלו דברים שנאמרו בירושלים. אין מלינין בה את המת. ואין מעבירין בתוכה עצמות אדם. ואין משכירין בתוכה בתים. ואין נותנין בתוכה מקום לגר תושב. ואין מקימין בה קברות חוץ מקברי בית דוד וקבר חלדה שהיו בה מימות נביאים הראשונים. ואין נוטעין בה גנות ופרדסים. ואינה נזרעת ואינה נחרשת שמא תסרח. ואין מקימין בה אילנות חוץ מגנת ורדים שהיתה שם מימות נביאים הראשונים. ואין מקימין בה אשפה מפני השרצים. ואין מוציאין הימנה זיזין וגזוזטראות לרשות הרבים מפני אהל הטמאה. ואין עושין בה כבשונות מפני העשן. ואין מגדלין בה תרנגולות מפני הקדשים. וכן לא יגדלו הכהנים תרנגולים בכל ארץ ישראל מפני הטהרות. ואין הבית נחלט בה. ואינו מטמא בנגעים. ואינה נעשית עיר הנדחת. ואינה מביאה עגלה ערופה לפי שלא נתחלקה לשבטים:"],
    [337,125,"הר הבית מקדש ממנה שאין זבין וזבות נדות ויולדות נכנסין לשם. ומתר להכניס המת עצמו להר הבית ואין צריך לומר טמא מת שהוא נכנס לשם:"],
    [337,126,"החיל מקדש ממנו שאין עכו\"ם וטמא מת ובועל נדה נכנסים לשם:"],
    [337,127,"עזרת הנשים מקדשת מן החיל שאין טבול יום נכנס לשם. ואסור זה מדבריהם אבל מן התורה מתר לטבול יום להכנס למחנה לויה. וטמא מת שנכנס לעזרת הנשים אינו חיב חטאת:"],
    [337,128,"עזרת ישראל מקדשת מעזרת נשים שאין מחסר כפורים נכנס לשם. וטמא שנכנס לשם חיב כרת:"],
    [337,129,"עזרת הכהנים מקדשת ממנה. שאין ישראל נכנסין לשם אלא בשעת צרכיהם לסמיכה ולכפרה ולשחיטה ולתנופה:"],
    [337,130,"בין האולם ולמזבח מקדש ממנה שאין בעלי מומין ופרועי ראש וקרועי בגדים נכנסין לשם:"],
    [337,131,"ההיכל מקדש מבין האולם ולמזבח. שאין נכנס לשם אלא רחוץ ידים ורגלים:"],
    [337,132,"בית קדש הקדשים מקדש ממנו שאין נכנס לשם אלא כהן גדול ביום הכפורים בשעת העבודה:"],
    [337,133,"מקום שהיה בעליה מכון על קדש הקדשים אין נכנסין לו אלא פעם אחת בשבוע לידע מה הוא צריך לחזק בדקו. בשעה שנכנסין הבנאים לבנות ולתקן בהיכל או להוציא משם את הטמאה. מצוה שיהיו הנכנסין כהנים תמימים. לא מצאו תמימים יכנסו בעלי מומין. ואם אין שם כהנים יכנסו לוים. לא מצאו לוים יכנסו ישראל. מצוה בטהורים. לא מצאו טהורים יכנסו טמאים. טמא ובעל מום יכנס בעל מום ואל יכנס טמא שהטמאה דחויה בצבור. וכל הנכנסין להיכל לתקן יכנסו בתבות. אם אין שם תבות או אי אפשר להם שיעשו בתבות יכנסו דרך פתחים:"],
    [337,135,"שמירת המקדש מצות עשה. ואף על פי שאין שם פחד מאויבים ולא מלסטים. שאין שמירתו אלא כבוד לו. אינו דומה פלטרין שיש עליו שומרין לפלטרין שאין עליו שומרין:"],
    [337,136,"ושמירה זו מצותה כל הלילה. והשומרים הם הכהנים והלוים שנאמר \"ואתה ובניך אתך לפני אהל העדת\". כלומר אתם תהיו שומרים לו. והרי נאמר \"ושמרו את משמרת אהל מועד\" ונאמר \"והחנים קדמה לפני אהל מועד מזרחה משה ואהרן ובניו שמרי משמרת הקדש\":"],
    [337,137,"ואם בטלו שמירה עברו בלא תעשה שנאמר \"ושמרו את משמרת הקדש\". ולשון שמירה אזהרה היא הא למדת ששמירתו מצות עשה. ובטול שמירתו מצות לא תעשה:"],
    [337,138,"מצות שמירתו שיהיו הכהנים שומרים מבפנים והלוים מבחוץ. וכ\"ד עדה שומרין אותו בכל לילה תמיד בכ\"ד מקום. הכהנים בשלשה מקומות והלוים בכ\"א מקום:"],
    [337,139,"והיכן היו שומרים. כהנים היו שומרים בבית אבטינס ובבית הניצוץ ובבית המוקד. בית אבטינס ובית הניצוץ היו עליות בנויות בצד שערי העזרה והרובין היו שומרים שם. בית המוקד כפה ובית גדול היה מקף רבדין של אבן וזקני בית אב של אותו היום היו ישנים שם ומפתחות העזרה בידם:"],
    [337,140,"לא היו הכהנים השומרים ישנים בבגדי כהנה אלא מקפלין אותן ומניחין אותן כנגד ראשיהן ולובשין בגדי עצמן וישנים על הארץ. כדרך כל שומרי חצרות המלכים שלא יישנו על המטות:"],
    [337,141,"ארע קרי לאחד מהן. הולך במסבה שתחת הקרקע שהמחלות הפתוחות להר הבית לא נתקדשו וטובל וחוזר ויושב אצל אחיו הכהנים עד שנפתחין השערים בבקר יוצא והולך לו:"],
    [337,142,"והיכן היו הלוים שומרים. על חמשה שערי הר הבית. ועל ארבע פנותיו מתוכו. ועל ארבע פנות העזרה מבחוץ שאסור לישב בעזרה. ועל חמשה שערי העזרה חוץ לעזרה שהרי הכהנים שומרים על שער המוקד ועל שער הניצוץ. הרי שמונה עשר מקום:"],
    [337,143,"ועוד שומרים בלשכת הקרבן ובלשכת הפרכת ואחורי בית הכפרת:"],
    [337,144,"ומעמידין ממנה אחד על כל משמרות השומרים. ואיש הר הבית היה נקרא. והיה מחזר על כל משמר ומשמר כל הלילה. ואבוקות דלוקות לפניו. וכל משמר שאינו עומד ואומר לו איש הר הבית שלום עליך נכר שהוא ישן חובטו במקלו. ורשות היה לו לשרף את כסותו עד שהיו אומרין בירושלים מה קול בעזרה קול בן לוי לוקה ובגדיו נשרפין שישן על משמרתו:"],
    [337,145,"בשחר קדם שיעלה עמוד השחר סמוך לו יבוא הממנה של מקדש וידפק על הכהנים שבבית המוקד והן פותחין לו. נטל את המפתח ופתח את השער הקטן שבין בית המוקד ובין העזרה ונכנס מבית המוקד לעזרה ונכנסו אחריו הכהנים ושתי אבוקות של אור בידם ונחלקו לשתי כתות. כת הולכת למזרח וכת הולכת למערב. והיו בודקין והולכין את כל העזרה עד שיגיעו שתי הכתות למקום בית עושי חביתין. הגיעו אלו ואלו אומרין שלום הכל שלום. והעמידו עושי חביתין לעשות חביתין:"],
    [337,146,"כסדר הזה עושין בכל לילה ולילה חוץ מלילי שבת שאין בידם אור אלא בודקין בנרות הדלוקין שם מערב שבת:"]
